class Solution:
    def maxCyclicPartitionScore(self, nums: List[int], k: int) -> int:
        n = len(nums)
        im = max(range(n), key=lambda i: nums[i])
        a = nums[im:] + nums[:im]
        NEG = float('-inf')
        dp = [[NEG] * (n + 1) for _ in range(k + 1)]
        dp[0][0] = 0
        for j in range(1, k + 1):
            for i in range(j, n + 1):
                mx, mn, best = NEG, NEG, NEG
                mx = mn = a[i - 1]
                for p in range(i - 1, j - 2, -1):
                    mx = max(mx, a[p]); mn = min(mn, a[p])
                    if dp[j - 1][p] != NEG:
                        best = max(best, dp[j - 1][p] + mx - mn)
                dp[j][i] = best
        return max(dp[j][n] for j in range(1, k + 1))

