class Solution {
public:
    int maxCyclicPartitionScore(vector<int>& nums, int k) {
        int n = nums.size();
        int im = max_element(nums.begin(), nums.end()) - nums.begin();
        vector<int> a(nums.begin() + im, nums.end());
        a.insert(a.end(), nums.begin(), nums.begin() + im);
        const long long NEG = LLONG_MIN / 4;
        vector<vector<long long>> dp(k + 1, vector<long long>(n + 1, NEG));
        dp[0][0] = 0;
        for (int j = 1; j <= k; j++)
            for (int i = j; i <= n; i++) {
                long long mx = a[i-1], mn = a[i-1], best = NEG;
                for (int p = i - 1; p >= j - 1; p--) {
                    mx = max(mx, (long long)a[p]);
                    mn = min(mn, (long long)a[p]);
                    if (dp[j-1][p] != NEG) best = max(best, dp[j-1][p] + mx - mn);
                }
                dp[j][i] = best;
            }
        long long ans = 0;
        for (int j = 1; j <= k; j++) ans = max(ans, dp[j][n]);
        return (int)ans;
    }
};

