class Solution {
    public int maxCyclicPartitionScore(int[] nums, int k) {
        int n = nums.length;
        int im = 0;
        for (int i = 1; i < n; i++) if (nums[i] > nums[im]) im = i;
        int[] a = new int[n];
        for (int i = 0; i < n; i++) a[i] = nums[(im + i) % n];
        long NEG = Long.MIN_VALUE / 4;
        long[][] dp = new long[k + 1][n + 1];
        for (long[] row : dp) Arrays.fill(row, NEG);
        dp[0][0] = 0;
        for (int j = 1; j <= k; j++)
            for (int i = j; i <= n; i++) {
                long mx = a[i-1], mn = a[i-1], best = NEG;
                for (int p = i - 1; p >= j - 1; p--) {
                    mx = Math.max(mx, a[p]);
                    mn = Math.min(mn, a[p]);
                    if (dp[j-1][p] != NEG) best = Math.max(best, dp[j-1][p] + mx - mn);
                }
                dp[j][i] = best;
            }
        long ans = 0;
        for (int j = 1; j <= k; j++) ans = Math.max(ans, dp[j][n]);
        return (int) ans;
    }
}

