var maxCyclicPartitionScore = function(nums, k) {
    const n = nums.length;
    let im = 0;
    for (let i = 1; i < n; i++) if (nums[i] > nums[im]) im = i;
    const a = [];
    for (let i = 0; i < n; i++) a.push(nums[(im + i) % n]);
    const NEG = -Infinity;
    const dp = Array.from({length: k + 1}, () => Array(n + 1).fill(NEG));
    dp[0][0] = 0;
    for (let j = 1; j <= k; j++)
        for (let i = j; i <= n; i++) {
            let mx = a[i-1], mn = a[i-1], best = NEG;
            for (let p = i - 1; p >= j - 1; p--) {
                mx = Math.max(mx, a[p]);
                mn = Math.min(mn, a[p]);
                if (dp[j-1][p] !== NEG) best = Math.max(best, dp[j-1][p] + mx - mn);
            }
            dp[j][i] = best;
        }
    let ans = 0;
    for (let j = 1; j <= k; j++) ans = Math.max(ans, dp[j][n]);
    return ans;
};
